public static async Task TryAppendAsync(
    McpDbContext db,
    string memoryId,
    string actionType,
    CancellationToken cancellationToken)
{
    var workspaceId = db.CurrentWorkspaceId;
    var turn = await (
            from entry in db.SessionLogTurns.IgnoreQueryFilters()
            join session in db.SessionLogs.IgnoreQueryFilters() on entry.SessionLogId equals session.Id
            where session.WorkspaceId == workspaceId || entry.WorkspaceId == workspaceId
            orderby entry.Id descending
            select entry)
        .FirstOrDefaultAsync(cancellationToken)
        .ConfigureAwait(false);
    if (turn is null)
        return;

    var order = await db.SessionLogActions
        .IgnoreQueryFilters()
        .CountAsync(action => action.SessionLogTurnId == turn.Id, cancellationToken)
        .ConfigureAwait(false);

    db.SessionLogActions.Add(new SessionLogActionEntity
    {
        WorkspaceId = string.IsNullOrEmpty(turn.WorkspaceId) ? workspaceId : turn.WorkspaceId,
        SessionLogTurnId = turn.Id,
        Order = order + 1,
        Type = "memory",
        Status = "completed",
        Description = $"{actionType} {memoryId}",
    });
    await db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
}

private async Task<WorkspaceMutationResult> CreateDatabaseAsync(WorkspaceCreateRequest request, CancellationToken ct)
{
    var normalized = NormalizePath(request.WorkspacePath);
    if (string.IsNullOrWhiteSpace(normalized))
        return new WorkspaceMutationResult(false, "WorkspacePath is required.");

    await s_writeLock.WaitAsync(ct).ConfigureAwait(false);
    try
    {
        await EnsureBootstrappedAsync(ct).ConfigureAwait(false);
        var existing = await _db!.Workspaces
            .IgnoreQueryFilters()
            .Include(w => w.BannedItems)
            .SingleOrDefaultAsync(w => w.WorkspaceId == normalized || w.WorkspacePath == normalized, ct)
            .ConfigureAwait(false);

        if (existing is { IsDeleted: false })
            return new WorkspaceMutationResult(false, $"Workspace already registered: {normalized}");

        var entry = CreateConfigEntry(request, normalized);
        WorkspaceEntity entity;
        if (existing is null)
        {
            entity = ToEntity(entry);
            _db.Workspaces.Add(entity);
        }
        else
        {
            ApplyConfigEntry(existing, entry);
            existing.IsDeleted = false;
            existing.DeletedAtUtc = null;
            existing.DeletedBy = null;
            existing.DeleteReason = null;
            entity = existing;
        }

        await using var transaction = await _db.Database.BeginTransactionAsync(ct).ConfigureAwait(false);
        try
        {
            await _db.SaveChangesAsync(ct).ConfigureAwait(false);
            var importFailure = await TryImportDumpAsync(request.DumpPath, normalized, ct).ConfigureAwait(false);
            if (importFailure is not null)
            {
                await transaction.RollbackAsync(ct).ConfigureAwait(false);
                _db.ChangeTracker.Clear();
                return importFailure;
            }

            await transaction.CommitAsync(ct).ConfigureAwait(false);
        }
        catch
        {
            await transaction.RollbackAsync(ct).ConfigureAwait(false);
            _db.ChangeTracker.Clear();
            throw;
        }

        await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
        _logger.LogInformation("Workspace created: {Name} at {Path}", entity.Name, entity.WorkspacePath);
        await PublishChangeSafeAsync(ChangeEventActions.Created, normalized, ct).ConfigureAwait(false);
        return new WorkspaceMutationResult(true, Workspace: await ToDtoAsync(entity, ct).ConfigureAwait(false));
    }
    finally
    {
        s_writeLock.Release();
    }
}

public async Task<WikiDumpImportResult> ImportAsync(WikiDumpImportRequest request, CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(request);
    cancellationToken.ThrowIfCancellationRequested();
    if (IsUnsafePath(request.DumpPath) || IsUnsafePath(request.DestinationWorkspacePath))
        return Fail("unsafe_path", "Dump or destination path is unsafe.");

    var dumpFile = ResolveDumpFile(request.DumpPath);
    if (dumpFile is null)
        return Fail("malformed_dump", "Dump path does not contain mcp-wiki-dump.json.");

    string json;
    try
    {
        json = await File.ReadAllTextAsync(dumpFile, cancellationToken).ConfigureAwait(false);
        JsonSerializer.Deserialize<WikiDumpDocument>(json, JsonOptions);
    }
    catch (JsonException)
    {
        return Fail("malformed_dump", "Dump JSON is malformed.");
    }

    var dump = JsonSerializer.Deserialize<WikiDumpDocument>(json, JsonOptions);
    if (dump is null)
        return Fail("malformed_dump", "Dump JSON is malformed.");
    if (!string.Equals(dump.SchemaVersion, WikiDumpDefaults.SchemaVersion, StringComparison.Ordinal))
        return Fail("version_mismatch", "Dump schemaVersion is not mcp-wiki-dump/v1.");
    if (dump.Tables.Count == 0)
        return Fail("missing_tables", "Dump tables[] is missing.");

    var expected = ComputeSha256(dump);
    if (!string.IsNullOrWhiteSpace(dump.Sha256) && !string.Equals(dump.Sha256, expected, StringComparison.OrdinalIgnoreCase))
        return Fail("hash_mismatch", "Dump sha256 does not match canonical bytes.");

    var destination = Path.GetFullPath(request.DestinationWorkspacePath);
    var diagnostics = new List<string>();
    var created = new List<string>();
    foreach (var todo in dump.Todos)
    {
        var exists = await _db.TodoItems.AnyAsync(item => item.Id == todo.Id, cancellationToken).ConfigureAwait(false);
        if (exists)
            continue;
        _db.TodoItems.Add(new TodoItemEntity
        {
            Id = todo.Id,
            Title = todo.Title,
            Section = todo.Section,
            Priority = todo.Priority,
            Done = todo.Done,
            WorkspaceId = destination,
        });
        created.Add(todo.Id);
    }

    foreach (var link in dump.TodoRequirementLinks)
    {
        var exists = await _db.TodoRequirementLinks.AnyAsync(
            item => item.TodoId == link.TodoId && item.RequirementId == link.RequirementId,
            cancellationToken).ConfigureAwait(false);
        if (exists)
            continue;
        _db.TodoRequirementLinks.Add(new TodoRequirementLinkEntity
        {
            WorkspaceId = destination,
            TodoId = link.TodoId,
            RequirementKind = link.RequirementKind,
            RequirementId = link.RequirementId,
            CreatedAtUtc = _time.GetUtcNow(),
        });
    }

    if (created.Count > 0 || dump.TodoRequirementLinks.Count > 0)
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    string? archive = null;
    var todoYaml = request.TodoYamlPath;
    if (string.IsNullOrWhiteSpace(todoYaml))
    {
        var sibling = Path.Combine(Path.GetDirectoryName(dumpFile) ?? destination, "todo.yaml");
        if (File.Exists(sibling))
            todoYaml = sibling;
        var destYaml = Path.Combine(destination, "docs", "todo.yaml");
        if (File.Exists(destYaml))
            todoYaml = destYaml;
    }

    if (!string.IsNullOrWhiteSpace(todoYaml) && File.Exists(todoYaml))
    {
        diagnostics.Add("dump_wins_over_todo_yaml: " + dumpFile + " | " + todoYaml);
        var archiveDir = Path.Combine(destination, ".mcpServer", "archive", "todo-yaml");
        Directory.CreateDirectory(archiveDir);
        archive = Path.Combine(archiveDir, "todo.yaml");
        File.Copy(todoYaml, archive, overwrite: true);
    }

    return new WikiDumpImportResult
    {
        Success = true,
        CreatedTodoIds = created,
        Diagnostics = diagnostics,
        TodoYamlArchivePath = archive,
    };
}

private async Task RestoreMemoryAsync(MemoryItem previous, CancellationToken cancellationToken)
{
    if (_db is not null)
    {
        await RestoreMemoryExactAsync(previous, cancellationToken).ConfigureAwait(false);
        return;
    }

    var rollback = await _memoryService.UpdateAsync(
            previous.Id,
            new MemoryUpdateRequest
            {
                Category = previous.Category,
                Scope = previous.Scope,
                Text = previous.Text,
                UpdatedBy = previous.UpdatedBy,
            },
            cancellationToken)
        .ConfigureAwait(false);

    if (rollback.Success)
        return;

    if (rollback.FailureKind == MemoryMutationFailureKind.NotFound)
    {
        await RestoreRemovedMemoryAsync(previous, cancellationToken).ConfigureAwait(false);
        return;
    }

    throw new InvalidOperationException(rollback.Error ?? $"Rollback update for memory '{previous.Id}' failed.");
}

private async Task RestoreRemovedMemoryAsync(MemoryItem previous, CancellationToken cancellationToken)
{
    if (_db is not null)
    {
        await RestoreMemoryExactAsync(previous, cancellationToken).ConfigureAwait(false);
        return;
    }

    var rollback = await _memoryService.AddAsync(
            new MemoryAddRequest
            {
                Id = previous.Id,
                Category = previous.Category,
                Scope = previous.Scope,
                Text = previous.Text,
                UpdatedBy = previous.UpdatedBy,
            },
            cancellationToken)
        .ConfigureAwait(false);

    if (!rollback.Success)
        throw new InvalidOperationException(rollback.Error ?? $"Rollback restore for memory '{previous.Id}' failed.");
}

private async Task RestoreMemoryExactAsync(MemoryItem previous, CancellationToken cancellationToken)
{
    if (_db is null)
        throw new InvalidOperationException("A database context is required for exact memory rollback restoration.");

    var entity = await _db.Memories
        .IgnoreQueryFilters()
        .FirstOrDefaultAsync(memory => memory.Id == previous.Id, cancellationToken)
        .ConfigureAwait(false);
    if (entity is null)
    {
        entity = new MemoryEntity
        {
            Id = previous.Id,
            Category = previous.Category,
            Scope = ToEntityScope(previous.Scope),
            WorkspaceId = previous.WorkspacePath,
            Text = previous.Text,
            Version = previous.Version,
            CreatedAtUtc = previous.CreatedAtUtc,
            UpdatedAtUtc = previous.UpdatedAtUtc,
            UpdatedBy = previous.UpdatedBy,
        };
        _db.Memories.Add(entity);
    }
    else
    {
        entity.Category = previous.Category;
        entity.Scope = ToEntityScope(previous.Scope);
        entity.WorkspaceId = previous.WorkspacePath;
        entity.Text = previous.Text;
        entity.Version = previous.Version;
        entity.CreatedAtUtc = previous.CreatedAtUtc;
        entity.UpdatedAtUtc = previous.UpdatedAtUtc;
        entity.UpdatedBy = previous.UpdatedBy;
    }

    var entry = _db.Entry(entity);
    SetShadowValue(entry, "IsDeleted", false);
    SetShadowValue(entry, "DeletedAtUtc", null);
    SetShadowValue(entry, "DeletedBy", null);
    SetShadowValue(entry, "DeleteReason", null);
    await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
}

private async Task RestoreSessionAsync(
    SessionGraphSnapshot snapshot,
    CancellationToken cancellationToken)
{
    await using var transaction = await _db.Database.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
    try
    {
        _db.ChangeTracker.Clear();
        var current = await SessionQuery(includeSoftDeleted: true)
            .FirstOrDefaultAsync(
                entity => entity.SourceType == snapshot.SourceType
                          && entity.SessionId == snapshot.SessionId
                          && entity.WorkspaceId == snapshot.WorkspaceId,
                cancellationToken)
            .ConfigureAwait(false);
        if (current is null)
        {
            if (snapshot.Session is not null)
                _db.SessionLogs.Add(CloneSession(snapshot.Session));
        }
        else if (snapshot.Session is null)
        {
            SoftDeleteSessionGraph(current, "transaction_rollback_removed_session");
        }
        else
        {
            RestoreSessionGraph(current, snapshot.Session);
        }

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
    }
    catch
    {
        await transaction.RollbackAsync(cancellationToken).ConfigureAwait(false);
        throw;
    }
}

private async Task RestoreCreatedSessionAsync(
